-- BAT-LIVE-BIDS: the homepage's headline number, recorded every hour, so the page can say what it is relative to.
--
-- Skylar 2026-09-27, looking at the live homepage: "i dont get what that market number represents its missing
-- relativity". The number is the sum of the current high bid on every public live BaT auction
-- (market_pulse_live()). Nothing kept its history, so the page could not say more or less than when.
--
-- Stored in the existing market_indexes / market_index_values organ (one row per UTC day,
-- UNIQUE (index_id, value_date)): open/close/high/low = first/latest/max/min hourly reading of the day,
-- volume = auctions with a bid at the latest reading, components_snapshot.hourly."HH" = {at, bids, n, by_make}.
-- Per-hour provenance: calculation_metadata.sources."HH" = 'live' for readings this function records,
-- otherwise calculation_metadata.source.
--
-- 1. record_bat_live_bids_snapshot(): reads the live board exactly as the homepage does (public live BaT lots,
--    current bid = COALESCE(high_bid, sale_price)) and writes this hour's reading. pg_cron runs it at :07
--    (the live sync runs at :00/:15/:30/:45). First reading taken when this file applies.
-- 2. Backfill 2026-06-29 .. 2026-09-19 (83 days x 24 hours = 1992 readings) rebuilt from the local BaT
--    archive's bid history: for each hour, the highest bid so far on every auction still open with a bid.
--    Totals only (the archive's make names differ from canonical_makes, so per-make readings come from live
--    ones). Only complete days: the archive holds ended auctions through 2026-09-26 19:19Z, so an hour is
--    complete once every auction open at it has ended (BaT runs 7 days) -> through 2026-09-19. Coverage:
--    13,743 of 14,285 auctions that ended in the last 12 weeks have bid history (96.2%), so rebuilt
--    readings may run up to ~4% low. Cross-check with the earlier ad hoc query: 2026-07-05 20:00Z
--    $34,230,900 / 920 and 2026-09-13 20:00Z $36,002,320 / 1,059 (identical).
-- 3. market_pulse_live() gains 'baseline': the reading 7 days ago at this hour (with its source) and the
--    range of readings at this UTC weekday and hour over the last 12 weeks (a board on Sunday evening is
--    compared with Sunday evenings, not Tuesdays). Everything else in the function is unchanged.

SET statement_timeout = '120s';

INSERT INTO public.market_indexes (index_code, index_name, description, calculation_method, components_query, is_active)
VALUES (
  'BAT-LIVE-BIDS',
  'BaT live bids',
  'Sum of the current high bid on every public live Bring a Trailer auction, read hourly (the nuke.ag homepage headline).',
  jsonb_build_object(
    'reading', 'sum(COALESCE(high_bid, sale_price)) over vehicles with sale_status = auction_live, platform_source = bringatrailer, auction_end_date > now(), is_public',
    'cadence', 'hourly at :07 UTC (pg_cron bat-live-bids-snapshot)',
    'backfill', 'highest bid so far per auction still open with a bid, rebuilt from the BaT archive (bid events), 2026-06-29..2026-09-19'
  ),
  'select public.record_bat_live_bids_snapshot()',
  true
)
ON CONFLICT (index_code) DO NOTHING;

CREATE OR REPLACE FUNCTION public.record_bat_live_bids_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path = public
AS $function$
DECLARE
  v_index uuid;
  v_at timestamptz := date_trunc('hour', now());
  v_hh text := to_char(date_trunc('hour', now()) AT TIME ZONE 'UTC', 'HH24');
  v_day date := (now() AT TIME ZONE 'UTC')::date;
  v_bids numeric;
  v_n int;
  v_snap jsonb;
BEGIN
  SELECT id INTO v_index FROM public.market_indexes WHERE index_code = 'BAT-LIVE-BIDS';
  IF v_index IS NULL THEN
    RAISE EXCEPTION 'market_indexes has no BAT-LIVE-BIDS row';
  END IF;

  WITH live AS (
    SELECT upper(COALESCE(cm.canonical_name, v.make, 'NO MAKE')) AS make,
           COALESCE(v.high_bid, v.sale_price) AS bid
    FROM public.vehicles v
    LEFT JOIN public.canonical_makes cm ON cm.id = v.canonical_make_id
    WHERE v.sale_status = 'auction_live'
      AND v.platform_source = 'bringatrailer'
      AND v.auction_end_date IS NOT NULL
      AND v.auction_end_date::timestamptz > now()
      AND v.is_public
  ), by_make AS (
    SELECT make, sum(bid) AS bids, count(bid) AS n FROM live GROUP BY make
  )
  SELECT (SELECT COALESCE(sum(bid), 0) FROM live),
         (SELECT count(bid) FROM live),
         (SELECT COALESCE(jsonb_object_agg(make, jsonb_build_array(bids, n)), '{}'::jsonb) FROM by_make)
    INTO v_bids, v_n, v_snap;

  v_snap := jsonb_build_object('at', v_at, 'bids', v_bids, 'n', v_n, 'by_make', v_snap);

  INSERT INTO public.market_index_values AS m
    (index_id, value_date, open_value, close_value, high_value, low_value, volume, components_snapshot, calculation_metadata)
  VALUES
    (v_index, v_day, v_bids, v_bids, v_bids, v_bids, v_n,
     jsonb_build_object('hourly', jsonb_build_object(v_hh, v_snap)),
     jsonb_build_object('source', 'live', 'sources', jsonb_build_object(v_hh, 'live')))
  ON CONFLICT (index_id, value_date) DO UPDATE SET
    close_value = EXCLUDED.close_value,
    high_value = GREATEST(m.high_value, EXCLUDED.high_value),
    low_value = LEAST(m.low_value, EXCLUDED.low_value),
    volume = EXCLUDED.volume,
    components_snapshot = jsonb_set(COALESCE(m.components_snapshot, '{}'::jsonb), '{hourly}',
                                    COALESCE(m.components_snapshot->'hourly', '{}'::jsonb) || jsonb_build_object(v_hh, v_snap)),
    calculation_metadata = jsonb_set(COALESCE(m.calculation_metadata, '{}'::jsonb), '{sources}',
                                     COALESCE(m.calculation_metadata->'sources', '{}'::jsonb) || jsonb_build_object(v_hh, 'live'));

  RETURN v_snap - 'by_make';
END;
$function$;

REVOKE ALL ON FUNCTION public.record_bat_live_bids_snapshot() FROM PUBLIC, anon, authenticated;

