--     JOIN market_indexes i ON i.id = v.index_id WHERE i.index_code = 'BAT-LIVE-BIDS' ORDER BY value_date DESC LIMIT 3;
--   SELECT public.market_pulse_live()->'baseline';   -- same_hour (weekday+hour) range from the backfill; week_ago null until 7 days of readings
--   SELECT jobname, schedule, active FROM cron.job WHERE jobname = 'bat-live-bids-snapshot';
